 "content": "def transform(grid):
    """Fill the overlap of matching colored horizontal markers with 4,
    in the vertical gap above the full-width 2 divider.
    """
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    divider = next((r for r, row in enumerate(grid) if all(v == 2 for v in row)), None)
    if divider is None:
        return out
    top = grid[0]
    bottom = grid[-1]
    for c in range(w):
        if top[c] != 0 and top[c] == bottom[c]:
            for r in range(1, divider):
                if grid[r][c] == 0:
                    out[r][c] = 4
    return out
